import re
L=open('docs/plans/2026-10-06-2025-feat-issue-dispatch-plan.md').read().split('\n')
defined=set(int(m.group(1)) for l in L for m in [re.match(r'^- AE(\d+)\.',l)] if m)
req=set()
for l in L:
    if l.startswith('- **Requirements:**'):
        for a,b in re.findall(r'AE(\d+)(?:〜AE(\d+))?',l):
            a=int(a); b=int(b) if b else a
            req.update(range(a,b+1))
covers={}
for i,l in enumerate(L,1):
    for m in re.finditer(r'Covers ((?:AE\d+(?:〜AE\d+)?(?:, )?)+)',l):
        for a,b in re.findall(r'AE(\d+)(?:〜AE(\d+))?',m.group(1)):
            a=int(a); b=int(b) if b else a
            for x in range(a,b+1): covers.setdefault(x,[]).append(i)
print('defined', len(defined), 'in req', len(req&defined))
print('not in any Requirements:', sorted(defined-req))
print('in Requirements but never Covers:', sorted((req&defined)-set(covers)))
print('Covers of missing:', {k:covers.get(k) for k in sorted(defined-req)})
EOF

