python3 - <<'EOF'
import re
L=open('docs/plans/2026-10-06-2025-feat-issue-dispatch-plan.md').read().split('\n')
def ex(s):
    out=set()
    for a,b in re.findall(r'AE(\d+)(?:〜AE(\d+))?',s):
        a=int(a); b=int(b) if b else a; out.update(range(a,b+1))
    return out
unit=None; req={}; cov={}
for l in L:
    m=re.match(r'^### (U\d+)\.',l)
    if m: unit=m.group(1); continue
    if l.startswith('## ') : unit=None
    if unit:
        if l.startswith('- **Requirements:**'): req[unit]=ex(l)
        for m in re.finditer(r'Covers ((?:AE\d+(?:〜AE\d+)?(?:, )?)+)',l): cov.setdefault(unit,set()).update(ex(m.group(1)))
for u in sorted(cov,key=lambda x:int(x[1:])):
    print(u,'covers not in req:',sorted(cov[u]-req.get(u,set())),' req not covered:',sorted(req.get(u,set())-cov[u]))
EOF

